  CONSTRAINT `jadwal_piket_id_guru_foreign` FOREIGN KEY (`id_guru`) REFERENCES `guru` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=5305 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

